var a=[{title:`Perché i liquidi contano`,text:`Il tuo corpo usa l’acqua per trasportare nutrienti, far circolare il sangue, controllare la temperatura e sostituire ciò che perdi con il sudore. Anche una lieve disidratazione può far sembrare più duro un esercizio intenso, soprattutto con il caldo. Nessuna quantità unica va bene per ogni atleta o ogni allenamento.`},{title:`Prima e durante un allenamento`,text:`Inizia ragionevolmente ben idratato e tieni l’acqua a portata di mano, soprattutto per sessioni lunghe o calde. Per le normali sessioni brevi, bere quando senti sete spesso basta. Caldo, attività lunga e intensa e sudorazione insolitamente abbondante possono richiedere un piano personale per bere. Reintegrare gli elettroliti può contare durante un esercizio lungo, ma un breve allenamento in palestra non lo richiede automaticamente. Se il caldo rende pericoloso un allenamento, allenati meno o spostati in un posto più fresco.`},{title:`Bere troppo`,text:`Bere grandi quantità a prescindere da sete o perdita di sudore può diluire il sodio nel sangue e causare iponatriemia associata all’esercizio. Aumentare di peso durante un lungo evento di resistenza può essere un segno che stai bevendo troppo. Forte mal di testa, confusione o vomito durante un esercizio lungo richiedono una valutazione medica urgente. Bere di più non è la soluzione.`},{title:`Controlli semplici`,text:`Sete, variazioni del peso corporeo attorno a sessioni lunghe, il meteo e la durata dell’allenamento possono tutti guidare quanto bevi. Il colore delle urine dà un indizio approssimativo, ma non è un test diagnostico. Se hai una condizione renale o cardiaca, chiedi al tuo medico un consiglio adatto a te.`}];var o=[{label:`NATA: reintegrazione dei liquidi nelle persone fisicamente attive`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC5634236/`},{label:`Wilderness Medical Society: iponatriemia associata all’esercizio`,url:`https://journals.sagepub.com/doi/full/10.1016/j.wem.2019.11.003`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};